// Code generated by Saltcorn. DO NOT EDIT.
// Rewritten on every build; edits here are lost.
//
// **The Astro server runtime** — what `astro/runtime/server` is to a real Astro
// build, reduced to what the `.astro` compiler's output calls, and written to
// run inside Saltcorn's code isolate instead of Node.
//
// `build.mjs` compiles every `.astro` file with `@astrojs/compiler` and points
// the compiled module's `import … from "astro/runtime/server/index.js"` here, so
// a page's frontmatter runs in the same isolate, with the same `db`, `fetch`,
// `fs`, `Table`, `user` and `lib` a JavaScript code action has: it is bundled
// *into* the body of one code run, and those are that run's parameters.
//
// The isolate has no Node and no `deno_web`. It has `Headers`, `Response`,
// `TextEncoder` and `btoa`/`atob` (Saltcorn's own), and no `URL`, timers or
// streams, which is why a few small pieces of the web platform are written out
// below rather than assumed.
//
// What is deliberately not here: UI-framework islands (`client:*` directives),
// view transitions, content collections, and streaming. Each fails by name.
//
// **The render cache.** The server keeps a rendered page for the next anonymous
// visitor until a table it read is written. So every answer says whether it
// may be kept (`cache`): not when the page read something that differs between
// visitors — a cookie, a request header, the CSRF token — and not when it set
// `Cache-Control: no-store`, which is how a page opts out.

// ---------------------------------------------------------------------------
// HTML strings
// ---------------------------------------------------------------------------

/** A string that is already HTML: rendered as it is, never escaped again. */
export class HTMLString {
  constructor(value) {
    this.value = String(value);
  }
  toString() {
    return this.value;
  }
}

const ESCAPES = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" };

/** Escape `value` for HTML text or a double-quoted attribute. */
export function escapeHTML(value) {
  return String(value).replace(/[&<>"']/g, (c) => ESCAPES[c]);
}

/** Mark `value` as HTML. What `set:html` compiles to. */
export function markHTMLString(value) {
  if (value instanceof HTMLString) return value;
  if (value === undefined || value === null) return new HTMLString("");
  return new HTMLString(value);
}

/** `set:html={…}`: the value is HTML, even when it is a promise of a string. */
export function unescapeHTML(value) {
  if (value && typeof value.then === "function") return value.then(markHTMLString);
  return markHTMLString(value);
}

// ---------------------------------------------------------------------------
// Templates: what `$$render\`…\`` builds
// ---------------------------------------------------------------------------

/** One compiled template: its literal HTML and the values between them. The
 * values were evaluated when the template literal was, so every child
 * component's render has already *started* — rendering is concurrent, and
 * only the concatenation is in order. */
export class RenderTemplate {
  constructor(strings, values) {
    this.strings = strings;
    this.values = values;
  }
  async toHTML() {
    let out = "";
    for (let i = 0; i < this.strings.length; i++) {
      out += this.strings[i];
      if (i < this.values.length) out += await renderValue(this.values[i]);
    }
    return out;
  }
}

/** The tag every compiled template is written with. */
export function render(strings, ...values) {
  return new RenderTemplate(strings, values);
}

/** A value in a template, as HTML. Text is escaped; `null`, `undefined` and
 * booleans render nothing, so `{cond && <p/>}` does what it says. */
export async function renderValue(value) {
  if (value === null || value === undefined || value === false || value === true) return "";
  if (value instanceof HTMLString) return value.value;
  if (value instanceof RenderTemplate) return value.toHTML();
  if (typeof value === "string") return escapeHTML(value);
  if (typeof value === "number" || typeof value === "bigint") return String(value);
  if (typeof value.then === "function") return renderValue(await value);
  if (Array.isArray(value)) {
    const parts = await Promise.all(value.map(renderValue));
    return parts.join("");
  }
  if (isResponse(value)) {
    throw new Error(
      "a component returned a Response; only a page's frontmatter may return one " +
        "(Astro.redirect or new Response(...))"
    );
  }
  if (typeof value === "function") {
    throw new Error(
      "a function was rendered as a value; call it, or render a component with <Name />"
    );
  }
  if (typeof value[Symbol.iterator] === "function") return renderValue([...value]);
  return escapeHTML(String(value));
}

// ---------------------------------------------------------------------------
// Attributes
// ---------------------------------------------------------------------------

/** `class:list={[…]}`: strings, arrays and `{ name: condition }` objects, with
 * duplicates dropped — Astro's own rule. */
function classList(value) {
  const out = [];
  const walk = (v) => {
    if (!v) return;
    if (typeof v === "string") out.push(...v.split(/\s+/).filter(Boolean));
    else if (Array.isArray(v)) v.forEach(walk);
    else if (v instanceof Set) v.forEach(walk);
    else if (typeof v === "object") {
      for (const [name, on] of Object.entries(v)) if (on) out.push(name);
    } else out.push(String(v));
  };
  walk(value);
  return [...new Set(out)].join(" ");
}

/** `style={{ fontSize: "2rem" }}` as a declaration list. */
function styleObject(value) {
  return Object.entries(value)
    .filter(([, v]) => v !== null && v !== undefined && v !== false && v !== "")
    .map(([k, v]) => {
      const name = k.startsWith("--") ? k : k.replace(/[A-Z]/g, (c) => "-" + c.toLowerCase());
      return `${name}:${v}`;
    })
    .join(";");
}

/** One attribute, ` name="value"`, or nothing. What `name={value}` compiles to. */
export function addAttribute(value, key, shouldEscape = true) {
  if (value === null || value === undefined || value === false) return "";
  if (key === "class:list") {
    const list = classList(value);
    return list ? markHTMLString(` class="${escapeHTML(list)}"`) : "";
  }
  if (key.startsWith("client:")) {
    throw new Error(
      `\`${key}\` hydrates a UI-framework component in the browser, which this framework ` +
        "does not do: render on the server, and add behaviour with a <script>"
    );
  }
  if (key.startsWith("server:") || key.startsWith("transition:")) {
    throw new Error(`\`${key}\` is not supported by the Saltcorn Astro framework`);
  }
  if (key === "style" && typeof value === "object" && !(value instanceof HTMLString)) {
    const css = styleObject(value);
    return css ? markHTMLString(` style="${escapeHTML(css)}"`) : "";
  }
  if (value === true) {
    // `data-*` and `aria-*` are strings, where `true` means "true"; elsewhere a
    // bare attribute is how HTML spells true.
    return markHTMLString(/^(data|aria)-/.test(key) ? ` ${key}="true"` : ` ${key}`);
  }
  const text = value instanceof HTMLString ? value.value : String(value);
  return markHTMLString(` ${key}="${shouldEscape ? escapeHTML(text) : text}"`);
}

/** `{...attrs}` on an element. `scoped` is the component's scope class, which a
 * spread must keep on the element it lands on. */
export function spreadAttributes(values = {}, _name, { class: scoped } = {}) {
  const attrs = { ...values };
  if (scoped) {
    if (attrs["class:list"] !== undefined) {
      attrs["class:list"] = [attrs["class:list"], scoped];
    } else if (attrs.class !== undefined && attrs.class !== null && attrs.class !== false) {
      attrs.class = `${attrs.class} ${scoped}`;
    } else {
      attrs.class = scoped;
    }
  }
  let out = "";
  for (const [key, value] of Object.entries(attrs)) out += addAttribute(value, key, true);
  return markHTMLString(out);
}

/** `<style define:vars={{ … }}>`: custom properties. */
export function defineStyleVars(defs) {
  let out = "";
  for (const def of [].concat(defs)) {
    for (const [k, v] of Object.entries(def || {})) {
      if (v !== undefined && v !== null && v !== false) out += `--${k}: ${v};`;
    }
  }
  return markHTMLString(out);
}

/** `<script define:vars={{ … }}>`: one `const` per variable. */
export function defineScriptVars(vars) {
  let out = "";
  for (const [k, v] of Object.entries(vars || {})) {
    if (!/^[A-Za-z_$][\w$]*$/.test(k)) throw new Error(`define:vars: \`${k}\` is not a JavaScript name`);
    out += `const ${k} = ${JSON.stringify(v)?.replace(/</g, "\\u003c")};\n`;
  }
  return markHTMLString(out);
}

// ---------------------------------------------------------------------------
// Components and slots
// ---------------------------------------------------------------------------

const FACTORY = Symbol.for("feldspar.astro.component");

/** `<Fragment>`: its children, and nothing around them. */
export const Fragment = Symbol.for("astro:fragment");

/** What an `.astro` file compiles to: the function its frontmatter and
 * template become, marked so `renderComponent` knows it from a plain function. */
export function createComponent(arg, moduleId) {
  const fn = typeof arg === "function" ? arg : arg.factory;
  fn[FACTORY] = true;
  fn.moduleId = moduleId ?? arg.moduleId;
  return fn;
}

/** Whether `value` is a component an `.astro` file (or this runtime) made. */
export function isAstroComponent(value) {
  return typeof value === "function" && value[FACTORY] === true;
}

/** No metadata is needed: there is no dev server and no hydration. */
export function createMetadata() {
  return {};
}

/** The module-level `Astro` — a placeholder the per-render one shadows. */
export function createAstro() {
  return {};
}

/** Render `<Component {...props}>slots</Component>`. */
export async function renderComponent(result, displayName, Component, props = {}, slots = {}) {
  for (const key of Object.keys(props)) {
    if (key.startsWith("client:")) {
      throw new Error(
        `<${displayName} ${key}>: islands (UI-framework components hydrated in the browser) ` +
          "are not supported; this framework renders everything on the server"
      );
    }
  }
  if (Component === Fragment) {
    return slots.default ? renderValue(slots.default(result)) : "";
  }
  if (typeof Component === "string") {
    // `<Tag />` where `const Tag = "h2"`: an element chosen at run time.
    let attrs = "";
    for (const [key, value] of Object.entries(props)) attrs += addAttribute(value, key);
    const inner = slots.default ? await renderValue(slots.default(result)) : "";
    if (VOID_ELEMENTS.has(Component.toLowerCase())) return markHTMLString(`<${Component}${attrs}>`);
    return markHTMLString(`<${Component}${attrs}>${inner}</${Component}>`);
  }
  if (isAstroComponent(Component)) {
    const out = await Component(result, props, slots);
    if (isResponse(out)) {
      throw new Error(
        `<${displayName}> returned a Response; only a page may redirect or answer ` +
          "with a Response"
      );
    }
    return markHTMLString(await renderValue(out));
  }
  if (Component === undefined || Component === null) {
    throw new Error(
      `<${displayName}> is undefined: check that it is imported, and that it is the ` +
        "default export of an .astro file"
    );
  }
  throw new Error(
    `<${displayName}> is not an .astro component. React, Vue, Svelte and other ` +
      "framework components are not supported by the Saltcorn Astro framework"
  );
}

const VOID_ELEMENTS = new Set([
  "area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta",
  "source", "track", "wbr",
]);

/** `<slot name="x">fallback</slot>`. */
export async function renderSlot(result, slotted, fallback) {
  if (slotted) return markHTMLString(await renderValue(slotted(result)));
  if (fallback !== undefined) return markHTMLString(await renderValue(fallback));
  return "";
}

/** Slots passed down from several places, later ones winning. */
export function mergeSlots(...sets) {
  const out = {};
  for (const set of sets) {
    if (!set) continue;
    if (typeof set === "function") {
      Object.assign(out, mergeSlots(set()));
    } else if (Array.isArray(set)) {
      Object.assign(out, mergeSlots(...set));
    } else {
      Object.assign(out, set);
    }
  }
  return out;
}

// ---------------------------------------------------------------------------
// The head: the site's stylesheet and the page's scripts
// ---------------------------------------------------------------------------

/** What goes in `<head>`: the stylesheet every page shares. Emitted once per
 * page, either where a layout's `<head>` closes or, for a page with no head,
 * before its first element (`maybeRenderHead`). */
export function renderHead(result) {
  result._headRendered = true;
  let out = "";
  for (const href of result.styles) out += `<link rel="stylesheet" href="${escapeHTML(href)}">`;
  return markHTMLString(out);
}

/** See `renderHead`. */
export function maybeRenderHead(result) {
  if (result._headRendered) return "";
  return renderHead(result);
}

/** A processed `<script>`: bundled at build time into a file under `/_astro/`,
 * so no inline script is needed and the strict CSP stands. Once per page. */
export function renderScript(result, id) {
  const src = result.scriptFor(id);
  if (!src || result._scripts.has(src)) return "";
  result._scripts.add(src);
  return markHTMLString(`<script type="module" src="${escapeHTML(src)}"></script>`);
}

export function renderTransition() {
  throw new Error("view transitions (transition:*) are not supported by the Saltcorn Astro framework");
}

export function createTransitionScope() {
  return renderTransition();
}

// ---------------------------------------------------------------------------
// The request
// ---------------------------------------------------------------------------

/** The parts of a URL a page reads — `Astro.url`. The isolate has no `URL`. */
export class PageURL {
  constructor(origin, path, query) {
    this.origin = origin;
    const [protocol, rest] = origin.includes("://") ? origin.split("://") : ["http", origin];
    this.protocol = protocol + ":";
    this.host = rest || "";
    this.hostname = this.host.replace(/:\d+$/, "");
    this.port = (this.host.match(/:(\d+)$/) || [])[1] || "";
    this.pathname = path;
    this.searchParams = new SearchParams(query);
    this.hash = "";
  }
  get search() {
    const s = this.searchParams.toString();
    return s ? "?" + s : "";
  }
  get href() {
    return this.origin + this.pathname + this.search;
  }
  toString() {
    return this.href;
  }
  toJSON() {
    return this.href;
  }
}

/** `URLSearchParams`, as much of it as a page reads, over decoded pairs. */
export class SearchParams {
  constructor(init) {
    this.pairs = [];
    if (Array.isArray(init)) this.pairs = init.map(([k, v]) => [String(k), String(v)]);
    else if (init && typeof init === "object") {
      for (const [k, v] of Object.entries(init)) this.pairs.push([k, String(v)]);
    }
  }
  get(name) {
    const found = this.pairs.find(([k]) => k === name);
    return found ? found[1] : null;
  }
  getAll(name) {
    return this.pairs.filter(([k]) => k === name).map(([, v]) => v);
  }
  has(name) {
    return this.pairs.some(([k]) => k === name);
  }
  append(name, value) {
    this.pairs.push([String(name), String(value)]);
  }
  set(name, value) {
    this.delete(name);
    this.append(name, value);
  }
  delete(name) {
    this.pairs = this.pairs.filter(([k]) => k !== name);
  }
  keys() {
    return this.pairs.map(([k]) => k)[Symbol.iterator]();
  }
  entries() {
    return this.pairs.map((p) => [...p])[Symbol.iterator]();
  }
  [Symbol.iterator]() {
    return this.entries();
  }
  toString() {
    const enc = (s) => encodeURIComponent(s).replace(/%20/g, "+");
    return this.pairs.map(([k, v]) => `${enc(k)}=${enc(v)}`).join("&");
  }
}

/** `Astro.request`: the method, URL and headers, and the body as a form, JSON
 * or text. The router hands the body over already parsed. */
export class PageRequest {
  constructor(input, url, vary) {
    this.method = input.method || "GET";
    this.url = url.href;
    this._headers = input.headers || {};
    this._vary = vary;
    this._form = input.form || null;
    this._json = input.json === undefined ? undefined : input.json;
  }
  /** The request's headers. Reading them makes the page this visitor's, so
   * the render cache does not keep it. */
  get headers() {
    visitorSpecific(this._vary);
    return new Headers(this._headers);
  }
  async formData() {
    if (!this._form) {
      throw new TypeError(
        "this request has no form body; a form must post as " +
          "application/x-www-form-urlencoded (the default for <form method=\"post\">)"
      );
    }
    return new SearchParams(this._form);
  }
  async json() {
    if (this._json === undefined) throw new TypeError("this request has no JSON body");
    return this._json;
  }
  async text() {
    if (this._json !== undefined) return JSON.stringify(this._json);
    if (this._form) return new SearchParams(this._form).toString();
    return "";
  }
}

function isResponse(value) {
  return typeof Response !== "undefined" && value instanceof Response;
}

/** Mark the page being rendered as one visitor's: it read something another
 * visitor's request would answer differently, so the render cache must not
 * serve it to anybody else. */
function visitorSpecific(vary) {
  if (vary) vary.cacheable = false;
}

/** `Astro.cookies`, over the request's cookies — every one but the server's
 * own session and CSRF cookies, which the router keeps back — and the
 * `Set-Cookie` headers a page adds. Reading or writing one makes the page this
 * visitor's. */
class Cookies {
  constructor(initial, response, vary) {
    this.values = { ...(initial || {}) };
    this.response = response;
    this.vary = vary;
  }
  get(name) {
    visitorSpecific(this.vary);
    const value = this.values[name];
    return value === undefined ? undefined : { value, json: () => JSON.parse(value) };
  }
  has(name) {
    visitorSpecific(this.vary);
    return this.values[name] !== undefined;
  }
  set(name, value, options = {}) {
    visitorSpecific(this.vary);
    const text = typeof value === "string" ? value : JSON.stringify(value);
    this.values[name] = text;
    let cookie = `${name}=${encodeURIComponent(text)}; Path=${options.path || "/"}`;
    if (options.maxAge !== undefined) cookie += `; Max-Age=${Number(options.maxAge)}`;
    if (options.httpOnly !== false) cookie += "; HttpOnly";
    if (options.secure) cookie += "; Secure";
    cookie += `; SameSite=${options.sameSite || "Lax"}`;
    this.response.headers.append("set-cookie", cookie);
  }
  delete(name, options = {}) {
    visitorSpecific(this.vary);
    delete this.values[name];
    this.response.headers.append(
      "set-cookie",
      `${name}=; Path=${options.path || "/"}; Max-Age=0`
    );
  }
}

// ---------------------------------------------------------------------------
// Rendering a page
// ---------------------------------------------------------------------------

/** The per-request state every component of one page shares — Astro's
 * `$$result` — and the `Astro` global each component's frontmatter gets. */
function createResult(site, page) {
  const response = { status: 200, statusText: "", headers: new Headers() };
  const result = {
    styles: site.styles,
    scriptFor: (id) => site.scripts[id],
    _headRendered: false,
    _scripts: new Set(),
    response,
    page,
  };
  const cookies = new Cookies(page.cookies, response, page.vary);
  const shared = {
    url: page.url,
    request: page.request,
    params: page.params,
    site: page.site,
    generator: "Saltcorn Feldspar (Astro)",
    locals: page.locals,
    cookies,
    response,
    currentLocale: page.locals.locale,
    redirect(location, status = 302) {
      return new Response(null, { status, headers: { location } });
    },
    rewrite() {
      throw new Error("Astro.rewrite is not supported by the Saltcorn Astro framework");
    },
  };
  result.createAstro = (...args) => {
    // `(props, slots)` from the current compiler, `(astroGlobal, props, slots)`
    // from older ones: the last two are what matter.
    const props = args.length >= 3 ? args[1] : args[0];
    const slots = args.length >= 3 ? args[2] : args[1];
    return {
      ...shared,
      props: props || {},
      slots: {
        has: (name) => Boolean(slots && slots[name]),
        render: async (name, callArgs) => {
          if (!slots || !slots[name]) return undefined;
          if (callArgs && callArgs.length) {
            throw new Error("Astro.slots.render with arguments is not supported");
          }
          return renderValue(slots[name](result));
        },
      },
    };
  };
  return result;
}

/** Render one page component to a response shape the host serves. */
export async function renderPage(site, Component, page, props = {}) {
  const result = createResult(site, page);
  const out = await Component(result, props, {});
  if (isResponse(out)) return responseShape(out);
  let html = await renderValue(out);
  if (!/^\s*<!doctype/i.test(html)) html = "<!DOCTYPE html>" + html;
  const headers = result.response.headers.__scPairs
    ? result.response.headers.__scPairs()
    : [...result.response.headers];
  if (!headers.some(([k]) => k === "content-type")) {
    headers.push(["content-type", "text/html; charset=utf-8"]);
  }
  return { status: result.response.status, headers, body: html, cache: cacheable(page, headers) };
}

/** Whether the render cache may keep this answer for the next visitor: the
 * page read nothing visitor-specific and did not say `no-store`. */
function cacheable(page, headers) {
  if (!page.vary || !page.vary.cacheable) return false;
  return !headers.some(
    ([k, v]) => (k === "cache-control" && /no-store|private/i.test(v)) || k === "set-cookie"
  );
}

/** A `Response` as the host's response shape. */
export async function responseShape(res) {
  const headers = res.headers.__scPairs ? res.headers.__scPairs() : [...res.headers];
  const body = await res.text();
  return { status: res.status, headers, body };
}

// ---------------------------------------------------------------------------
// Routing
// ---------------------------------------------------------------------------

/** A route file's path under `src/pages`, as Astro reads it:
 * `blog/[slug].astro` is `/blog/:slug`, `[...path].astro` is a rest parameter,
 * `index` is the directory itself, and an endpoint keeps its extension
 * (`rss.xml.ts` is `/rss.xml`). */
export function parseRoute(file) {
  let path = file.replace(/\.(astro|js|ts|mjs|mts)$/, "");
  path = path.replace(/(^|\/)index$/, "");
  const segments = path.split("/").filter(Boolean).map((part) => {
    const rest = part.match(/^\[\.\.\.(\w+)\]$/);
    if (rest) return { rest: rest[1] };
    const param = part.match(/^\[(\w+)\]$/);
    if (param) return { param: param[1] };
    if (/[[\]]/.test(part)) {
      throw new Error(
        `src/pages/${file}: a segment must be all text, all [param] or all [...rest]`
      );
    }
    return { text: part };
  });
  return segments;
}

/** Most specific first, segment by segment: text, then a param, then a rest.
 * Of two routes that agree as far as the shorter goes, the shorter wins — the
 * longer can only match the same path through an empty rest. */
export function compareRoutes(a, b) {
  const rank = (s) => (s.text !== undefined ? 0 : s.param !== undefined ? 1 : 2);
  for (let i = 0; i < Math.max(a.segments.length, b.segments.length); i++) {
    if (i >= a.segments.length) return -1;
    if (i >= b.segments.length) return 1;
    const diff = rank(a.segments[i]) - rank(b.segments[i]);
    if (diff !== 0) return diff;
  }
  return 0;
}

/** Match `path` against one route, answering its params or `null`. */
export function matchRoute(route, path) {
  const parts = path.split("/").filter(Boolean).map(decodeSegment);
  const params = {};
  let i = 0;
  for (let s = 0; s < route.segments.length; s++) {
    const seg = route.segments[s];
    if (seg.rest !== undefined) {
      const left = route.segments.length - s - 1;
      const take = parts.length - i - left;
      if (take < 0) return null;
      params[seg.rest] = take === 0 ? undefined : parts.slice(i, i + take).join("/");
      i += take;
      continue;
    }
    if (i >= parts.length) return null;
    if (seg.text !== undefined) {
      if (parts[i] !== seg.text) return null;
    } else {
      params[seg.param] = parts[i];
    }
    i++;
  }
  return i === parts.length ? params : null;
}

function decodeSegment(s) {
  try {
    return decodeURIComponent(s);
  } catch {
    return s;
  }
}

/** The path a route has for `params` — what a prerendered page is written to. */
export function routePath(route, params) {
  const parts = [];
  for (const seg of route.segments) {
    if (seg.text !== undefined) parts.push(seg.text);
    else {
      const value = params[seg.param ?? seg.rest];
      if (value === undefined || value === null || value === "") {
        if (seg.rest !== undefined) continue;
        throw new Error(`getStaticPaths in ${route.file} gave no value for \`${seg.param}\``);
      }
      parts.push(
        seg.rest !== undefined
          ? String(value).split("/").map(encodeURIComponent).join("/")
          : encodeURIComponent(String(value))
      );
    }
  }
  return "/" + parts.join("/");
}

/** The params and props `getStaticPaths` gives for `params`, or `null` when it
 * lists no such page. */
async function staticEntry(route, params) {
  const entries = await route.module.getStaticPaths({ paginate });
  for (const entry of entries || []) {
    const p = entry.params || {};
    const same = Object.keys(params).every(
      (k) => (p[k] === undefined || p[k] === null ? undefined : String(p[k])) === params[k]
    );
    if (same) return entry;
  }
  return null;
}

/** `paginate(items, { pageSize })` in `getStaticPaths`, as Astro has it. */
function paginate(items, { pageSize = 10, params = {}, props = {} } = {}) {
  const pages = Math.max(1, Math.ceil(items.length / pageSize));
  return Array.from({ length: pages }, (_, i) => {
    const n = i + 1;
    return {
      params: { ...params, page: n === 1 ? undefined : String(n) },
      props: {
        ...props,
        page: {
          data: items.slice(i * pageSize, n * pageSize),
          start: i * pageSize,
          end: Math.min(n * pageSize, items.length) - 1,
          size: pageSize,
          total: items.length,
          currentPage: n,
          lastPage: pages,
        },
      },
    };
  });
}

// ---------------------------------------------------------------------------
// The entry point: one call per request
// ---------------------------------------------------------------------------

/** Build the site object `handle` serves from what `build.mjs` generated. */
export function createSite({ routes, styles, scripts, site }) {
  const ordered = routes
    .map((r) => ({ ...r, segments: parseRoute(r.file) }))
    .sort(compareRoutes);
  return { routes: ordered, styles, scripts, site };
}

/** The page context for one request. `input` is what the host bound as
 * `request`: `{ method, path, query, headers, form, json, origin, locale,
 * csrfToken, mode }`. `who` is the run's `user`, if any. */
function pageContext(site, input, path, params, who) {
  const origin = site.site || input.origin || "";
  const url = new PageURL(origin.replace(/\/$/, ""), path, Object.entries(input.query || {}));
  const vary = { cacheable: true };
  const csrfToken = input.csrfToken || "";
  return {
    url,
    params,
    site: site.site ? new PageURL(site.site.replace(/\/$/, ""), "/", []) : undefined,
    request: new PageRequest(input, url, vary),
    cookies: input.cookies,
    vary,
    locals: {
      user: who ?? null,
      locale: input.locale,
      // The token is this browser's, so a page that renders it is too.
      get csrfToken() {
        visitorSpecific(vary);
        return csrfToken;
      },
    },
  };
}

/** Find the route for `path`, rendering it with `who` as the visitor. */
async function serve(site, input, who) {
  const path = input.path || "/";
  for (const route of site.routes) {
    if (route.file === "404.astro" || route.file === "500.astro") continue;
    const params = matchRoute(route, path);
    if (!params) continue;
    let props = {};
    if (route.prerender && route.module.getStaticPaths) {
      const entry = await staticEntry(route, params);
      if (!entry) continue;
      props = entry.props || {};
    }
    const page = pageContext(site, input, path, params, who);
    if (route.endpoint) return endpoint(route, page, input.method || "GET");
    return renderPage(site, route.module.default, page, props);
  }
  if (path === "/sitemap.xml") return sitemap(site, input);
  if (path === "/robots.txt") return robots(site, input);
  return notFound(site, input, who);
}

/** The site's origin for an absolute link: the setting, else this request's. */
function originOf(site, input) {
  return (site.site || input.origin || "").replace(/\/$/, "");
}

/** `/sitemap.xml`, when no page claims it: every route with no params, and the
 * pages each dynamic route's `getStaticPaths()` lists — prerendered or not, so
 * a server-rendered `[slug].astro` lists its pages by exporting one. */
async function sitemap(site, input) {
  const origin = originOf(site, input);
  const paths = new Set();
  for (const route of site.routes) {
    if (route.endpoint || route.file === "404.astro" || route.file === "500.astro") continue;
    if (route.segments.every((s) => s.text !== undefined)) {
      paths.add(routePath(route, {}));
    } else if (route.module.getStaticPaths) {
      for (const entry of (await route.module.getStaticPaths({ paginate })) || []) {
        paths.add(routePath(route, entry.params || {}));
      }
    }
  }
  const urls = [...paths]
    .sort()
    .map((p) => `<url><loc>${escapeHTML(origin + p)}</loc></url>`)
    .join("");
  return {
    status: 200,
    headers: [["content-type", "application/xml; charset=utf-8"]],
    body:
      '<?xml version="1.0" encoding="UTF-8"?>' +
      `<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${urls}</urlset>`,
    cache: true,
  };
}

/** `/robots.txt`, when neither a page nor `public/` has one: everything is
 * allowed, and the sitemap is named. */
function robots(site, input) {
  const origin = originOf(site, input);
  return {
    status: 200,
    headers: [["content-type", "text/plain; charset=utf-8"]],
    body: `User-agent: *\nAllow: /\n${origin ? `Sitemap: ${origin}/sitemap.xml\n` : ""}`,
    cache: true,
  };
}

/** `src/pages/404.astro` with a 404, or a plain page if there is none. */
async function notFound(site, input, who) {
  const route = site.routes.find((r) => r.file === "404.astro");
  if (!route) {
    return {
      status: 404,
      headers: [["content-type", "text/html; charset=utf-8"]],
      body: "<!DOCTYPE html><title>Not found</title><h1>Not found</h1>",
      cache: true,
    };
  }
  const page = pageContext(site, input, input.path || "/", {}, who);
  const out = await renderPage(site, route.module.default, page);
  return { ...out, status: out.status === 200 ? 404 : out.status };
}

/** `src/pages/500.astro`, for a render that failed: the page gets the error as
 * `Astro.props.error` (its `message` is the one a visitor may be shown) and is
 * answered with a 500. `null` when the site has no such page, so the server
 * answers its own error response. */
async function serverError(site, input, who) {
  const route = site.routes.find((r) => r.file === "500.astro");
  if (!route) return null;
  const page = pageContext(site, input, input.path || "/", {}, who);
  const error = new Error(String(input.error || "Internal error"));
  const out = await renderPage(site, route.module.default, page, { error });
  return { ...out, status: 500, cache: false };
}

/** An endpoint file (`rss.xml.ts`): its exported `GET`/`POST`/… (or `ALL`). */
async function endpoint(route, page, method) {
  const handler = route.module[method] || route.module.ALL;
  if (!handler) {
    return { status: 405, headers: [["content-type", "text/plain"]], body: "method not allowed" };
  }
  const out = await handler({
    params: page.params,
    request: page.request,
    url: page.url,
    site: page.site,
    locals: page.locals,
    redirect: (location, status = 302) => new Response(null, { status, headers: { location } }),
  });
  if (!isResponse(out)) {
    throw new Error(`${route.file}: ${method} must return a Response`);
  }
  const shape = await responseShape(out);
  return { ...shape, cache: cacheable(page, shape.headers) };
}

/** The pages to write at build time: every route that says
 * `export const prerender = true`, each of a dynamic one's `getStaticPaths`. */
async function prerenderList(site) {
  const out = [];
  const refresh = [];
  for (const route of site.routes) {
    if (!route.prerender || route.file === "500.astro") continue;
    const dynamic = route.segments.some((s) => s.text === undefined);
    if (!dynamic) {
      out.push(routePath(route, {}));
      if (route.refresh) refresh.push(routePath(route, {}));
      continue;
    }
    if (!route.module.getStaticPaths) {
      throw new Error(
        `src/pages/${route.file} is prerendered and has [params], so it must export ` +
          "getStaticPaths()"
      );
    }
    for (const entry of (await route.module.getStaticPaths({ paginate })) || []) {
      out.push(routePath(route, entry.params || {}));
      if (route.refresh) refresh.push(routePath(route, entry.params || {}));
    }
  }
  // The 404 page is always written, so a missing static file costs nothing.
  if (site.routes.some((r) => r.file === "404.astro" && r.prerender)) out.push("/404");
  return { paths: [...new Set(out)], refresh: [...new Set(refresh)] };
}

/** One call from the host. `mode` is `render` (a request), `prerender-list`
 * (the build asking which pages to write, and which of them to refresh when
 * their data changes), `prerender` (one of them), or `error` (a render failed
 * with `input.error`: the site's 500 page, or `null`). */
export async function handle(site, input, who) {
  if (input.mode === "prerender-list") return prerenderList(site);
  if (input.mode === "prerender" && input.path === "/404") return notFound(site, input, null);
  if (input.mode === "error") return serverError(site, input, who);
  return serve(site, input, input.mode === "prerender" ? null : who);
}

// ---------------------------------------------------------------------------
// `feldspar:components` — what Saltcorn adds to Astro
// ---------------------------------------------------------------------------

/** `<Image src={imported} alt="…" width={400} />`: an image resized on the
 * server. `src` is an imported image (`import hero from "../hero.jpg"`, which
 * carries its `width` and `height`) or a URL string, used as it is. Give a
 * `width`, a `height` or both — the other follows the image's aspect ratio, and
 * both crop to fill — and optionally `format` (`webp`, `png`, `jpeg`),
 * `quality` (1–100), and `widths` with `sizes` for a `srcset`. An image is never
 * made larger than it is. The resized files are made on first request and kept
 * (`/_image?…`); an SVG is not resized. */
export const Image = createComponent(async (result, props) => {
  const { src, alt, width, height, format, quality, widths, sizes, ...rest } = props || {};
  if (alt === undefined || alt === null) {
    throw new Error(
      "<Image> needs an `alt`: describe the image, or write alt=\"\" for one that is " +
        "only decoration"
    );
  }
  if (!src) throw new Error("<Image> needs a `src`: an imported image or a URL");
  const attrs = { alt, loading: "lazy", decoding: "async", ...rest };
  if (typeof src === "string") {
    return markHTMLString(`<img${spreadAttributes({ src, width, height, ...attrs })}>`);
  }
  const box = imageBox(src, width, height);
  if (src.format === "svg" || !src.width || !src.height) {
    return markHTMLString(
      `<img${spreadAttributes({ src: src.src, width: box.width, height: box.height, ...attrs })}>`
    );
  }
  const cropped = width !== undefined && height !== undefined;
  const url = (w) => {
    const h = cropped ? Math.max(1, Math.round((w * box.height) / box.width)) : undefined;
    return imageUrl(src, w, h, format, quality);
  };
  const out = { src: url(box.width), width: box.width, height: box.height, ...attrs };
  if (Array.isArray(widths) && widths.length) {
    const list = [...new Set(widths.map((w) => Math.min(Math.round(Number(w)), src.width)))]
      .filter((w) => w > 0)
      .sort((a, b) => a - b);
    out.srcset = list.map((w) => `${url(w)} ${w}w`).join(", ");
    if (sizes) out.sizes = sizes;
  }
  return markHTMLString(`<img${spreadAttributes(out)}>`);
}, "feldspar:components/Image");

/** The size an `<Image>` is drawn at: what was asked, the rest from the aspect
 * ratio, never larger than the image itself. */
export function imageBox(image, width, height) {
  const iw = Number(image.width) || 0;
  const ih = Number(image.height) || 0;
  let w = width === undefined ? undefined : Math.round(Number(width));
  let h = height === undefined ? undefined : Math.round(Number(height));
  if (!iw || !ih) return { width: w, height: h };
  if (w === undefined && h === undefined) return { width: iw, height: ih };
  if (w === undefined) w = Math.round((h * iw) / ih);
  if (h === undefined) h = Math.round((w * ih) / iw);
  // Scale both down together when either is larger than the image.
  const scale = Math.min(1, iw / w, ih / h);
  return { width: Math.max(1, Math.round(w * scale)), height: Math.max(1, Math.round(h * scale)) };
}

/** The URL of one resized variant, or the original when nothing changes. */
function imageUrl(image, w, h, format, quality) {
  const same = w === image.width && h === undefined && !format && quality === undefined;
  if (same) return image.src;
  let url = `/_image?src=${encodeURIComponent(image.src)}&w=${w}`;
  if (h !== undefined) url += `&h=${h}`;
  if (format) url += `&f=${encodeURIComponent(String(format).toLowerCase())}`;
  if (quality !== undefined) url += `&q=${Math.round(Number(quality))}`;
  return url;
}

/** `<Csrf />`: the hidden field a form posting back to a page must carry. */
export const Csrf = createComponent(async (result) => {
  const token = result.page.locals.csrfToken;
  return markHTMLString(`<input type="hidden" name="_csrf" value="${escapeHTML(token)}">`);
}, "feldspar:components/Csrf");
